target.css:
:root {
  --ink: #1e2933;
  --muted: #66717d;
  --paper: #fffdf7;
  --line: #dce2dc;
  --navy: #263c50;
  --coral: #e66d59;
  --gold: #e8b84e;
  --mint: #78bda9;
  --soft-gold: #fff3cf;
  --soft-mint: #e8f5ef;
}

.vault-panel {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.console-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 11px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.card-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.title-block h1 {
  margin: 3px 0 0;
  color: var(--navy);
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.status-pill {
  padding: 5px 8px;
  border-radius: 99px;
  background: var(--soft-mint);
  color: var(--mint);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.console-grid {
  display: grid;
  grid-template-columns: 0.92fr 1.35fr 1.13fr;
  gap: 9px;
  padding: 10px 16px;
}

.dial-card,
.clue-card,
.team-card {
  min-height: 126px;
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.dial-card {
  display: flex;
  flex-direction: column;
  padding: 12px;
  background: var(--navy);
}

.dial-card .card-label {
  color: var(--soft-gold);
}

.dial-card strong {
  margin-top: 12px;
  color: var(--paper);
  font-size: 25px;
  line-height: 1;
  letter-spacing: 1px;
}

.dial-card span {
  margin-top: 4px;
  color: var(--line);
  font-size: 10px;
}

.dial-track {
  height: 5px;
  margin-top: auto;
  overflow: hidden;
  border-radius: 99px;
  background: var(--muted);
}

.dial-track i {
  display: block;
  width: 62%;
  height: 100%;
  border-radius: inherit;
  background: var(--gold);
}

.clue-card {
  display: flex;
  flex-direction: column;
  padding: 11px 12px 9px;
  background: var(--soft-gold);
  border-color: var(--gold);
}

.clue-card header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.clue-number {
  color: var(--coral);
  font-size: 17px;
  font-weight: 800;
  line-height: 1;
}

.clue-copy {
  margin: 10px 0 auto;
  color: var(--navy);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.3;
}

.clue-card footer {
  padding-top: 7px;
  border-top: 1px dashed var(--gold);
  color: var(--muted);
  font-size: 10px;
}

.clue-card footer span {
  color: var(--coral);
  font-size: 14px;
  font-weight: 800;
}

.team-card {
  padding: 11px 10px;
  background: var(--paper);
}

.team-card ul {
  display: grid;
  gap: 7px;
  margin: 9px 0 0;
  padding: 0;
  list-style: none;
}

.team-card li {
  display: grid;
  grid-template-columns: 20px 1fr auto;
  align-items: center;
  gap: 5px;
  font-size: 10px;
}

.avatar {
  display: grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border-radius: 7px;
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
}

.avatar.coral { background: var(--coral); }
.avatar.gold { background: var(--gold); }
.avatar.mint { background: var(--mint); }

.team-card b {
  color: var(--ink);
  font-size: 10px;
}

.team-card em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.console-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px 11px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.console-footer > span i {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--mint);
}

.console-footer button {
  padding: 7px 9px;
  border: 0;
  border-radius: 8px;
  background: var(--coral);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

.console-footer button b {
  margin-left: 5px;
  font-size: 14px;
}

